'use client';
import {useEffect,useRef,useState,type ReactNode} from 'react';
import type {Booking,HotelWorkspace} from '@/lib/pilot';
import {maintenanceAssignmentInterval,roomMaintenanceOverlaps} from '@/lib/maintenance';
export function QuickCheckIn({booking,workspace,busy,onCheckIn,onReviewBill,paymentContent,initialRoom=''}:{paymentContent?:ReactNode;initialRoom?:string;booking:Booking;workspace:HotelWorkspace;busy:boolean;onCheckIn:(room:string,overrideReason?:string)=>void;onReviewBill:()=>void}){
 const [paymentOpen,setPaymentOpen]=useState(!!initialRoom);const paymentHeading=useRef<HTMLHeadingElement>(null);
 const manager=['owner','manager'].includes(workspace.role);
 const [override,setOverride]=useState(false),[reason,setReason]=useState('');
 const [room,setRoom]=useState(initialRoom),[confirmed,setConfirmed]=useState(false);
 const interval=maintenanceAssignmentInterval(workspace.business_date,booking.departure,!!booking.inventory_overdue);
 const rooms=workspace.rooms.filter(r=>r.room_type_id===booking.room_type_id&&((r.status==='Clean'&&!r.open_turnover_task)||(manager&&override&&r.status==='Dirty'))&&!workspace.reservations.some(s=>s.id!==booking.id&&s.physical_room_id===r.id&&(s.status==='In house'||s.status==='Confirmed'&&!!s.arrival&&!!s.departure&&s.arrival<booking.departure!&&s.departure>workspace.business_date))&&!roomMaintenanceOverlaps(r,interval.start,interval.end));
 const statusReady=booking.status==='Confirmed';
 const dateReady=!!booking.arrival&&!!booking.departure&&booking.arrival<=workspace.business_date&&booking.departure>workspace.business_date;
 const paymentVisible=!!paymentContent&&paymentOpen&&rooms.some(r=>r.id===room);
 useEffect(()=>{if(paymentVisible){paymentHeading.current?.scrollIntoView?.({block:'start'});paymentHeading.current?.focus()}},[paymentVisible]);
 const selectedStatus=rooms.find(r=>r.id===room)?.status;
 useEffect(()=>{setConfirmed(false)},[booking.id,booking.guest_name,booking.arrival,booking.departure,booking.status,workspace.business_date,workspace.role,selectedStatus]);
 const dirty=rooms.find(r=>r.id===room)?.status==='Dirty';
 return <section className="quick-check-in"><h3>Check in guest</h3><ol><li><b>Confirm guest and stay</b><p>{booking.guest_name||'Guest name not recorded'} · {booking.arrival} to {booking.departure}</p></li><li><b>Choose a room</b>{manager&&<label className="pilot-check"><input type="checkbox" disabled={busy} checked={override} onChange={e=>{setOverride(e.target.checked);setConfirmed(false);setReason('')}}/>Allow dirty room — manager override</label>}<label className="field">Choose a room<select value={room} disabled={busy} onChange={e=>{setRoom(e.target.value);setPaymentOpen(!!e.target.value);setConfirmed(false);setReason('')}}><option value="">Select a room</option>{rooms.map(r=><option value={r.id} key={r.id}>{r.label} · {r.status}</option>)}</select></label>{!rooms.length&&<output>No clean, vacant room is ready for this stay. Review housekeeping or room availability.</output>}</li><li><b>Payment</b><p>{room&&rooms.some(r=>r.id===room)?'Review payment for your selected room before checking in.':'Choose a room to continue to payment.'}</p>{paymentContent&&room&&rooms.some(r=>r.id===room)&&!paymentVisible&&<button type="button" className="secondary" disabled={busy} onClick={()=>{setPaymentOpen(true);setConfirmed(false)}}>Review payment</button>}<p><button type="button" className="text-button" disabled={busy} onClick={onReviewBill}>Open guest bill</button></p></li></ol>{paymentVisible&&<section><h3 tabIndex={-1} ref={paymentHeading}>Payment for room {rooms.find(r=>r.id===room)?.label}</h3>{paymentContent}<p>{manager?'Record payment received above, or verify an existing payment arrangement before continuing.':'Verify the recorded payment or an approved payment arrangement before continuing. Ask an owner or manager to record a payment if needed.'} Continuing does not charge a card.</p><button type="button" className="primary" disabled={busy} onClick={()=>{setPaymentOpen(false);setConfirmed(false)}}>Continue to check-in</button></section>}{dirty&&<div className="pilot-notice"><p>This room is not ready. Your override will be recorded. The room stays Dirty and its preparation work remains open.</p><label className="field">Override reason<input value={reason} minLength={4} maxLength={500} disabled={busy} onChange={e=>{setReason(e.target.value);setConfirmed(false)}}/></label></div>}{!statusReady&&<p role="alert" className="pilot-error">This reservation is {booking.status.toLowerCase()}. Only confirmed reservations can check in. Refresh the reservation before continuing.</p>}{!dateReady&&<p className="pilot-error">Check-in is available during the booked stay dates. Review the arrival and departure before continuing.</p>}{!paymentVisible&&<><h3>Complete check-in</h3><label className="precheck-confirm"><input type="checkbox" checked={confirmed} disabled={busy} onChange={e=>setConfirmed(e.target.checked)}/> I verified the guest, stay details, and payment arrangements.</label><button className="primary" type="button" disabled={busy||!confirmed||!statusReady||!dateReady||!rooms.some(r=>r.id===room)||(dirty&&(reason.trim().length<4||reason.length>500||Array.from(reason).some(c=>c.charCodeAt(0)<32||c.charCodeAt(0)===127)))} onClick={()=>onCheckIn(room,dirty?reason.trim():undefined)}>{busy?'Checking in…':'Confirm check-in'}</button></>}</section>
}
